P = F = 0
def check(name, ok, info=""):
    global P, F
    if ok: P += 1
    else: F += 1
    print(("PASS" if ok else "FAIL") + f": {name}" + (f"  [{info}]" if info else ""))

M0 = 1.0
s1 = np.array([[0, 1], [1, 0]], complex); s2 = np.array([[0, -1j], [1j, 0]]); s3 = np.diag([1., -1]).astype(complex)
I2 = np.eye(2); Z2 = 0 * I2
G4 = [np.block([[Z2, -1j * s], [1j * s, Z2]]) for s in (s1, s2, s3)] + [np.block([[Z2, I2], [I2, Z2]])]
G5 = G4[0] @ G4[1] @ G4[2] @ G4[3]; E4 = np.eye(4)
YS = [1 / 6, -1 / 2, -2 / 3, 1 / 3, 1.0]; MULT = np.array([6, 2, 3, 3, 1])     # Q, L, u^c, d^c, e^c (nu: Y = 0)
W16 = MULT * np.array(YS); WL = np.array([0, -1.0, 0, 0, 0])
GAM = 2 / (4 * np.pi ** 2); GAML = -0.5 / (4 * np.pi ** 2)      # one charge-1 Weyl; lone doublet (2 sum m Y^3)/(4pi^2)

def block_static(L):
    n = 4 * L * L; X = np.zeros((n, n), complex); Xr = X.reshape(L, L, 4, L, L, 4)
    for mu in (0, 2):
        fw = (G4[mu] - E4) / 2; bw = -(G4[mu] + E4) / 2
        for x in range(L):
            for z in range(L):
                if mu == 0: Xr[x, z, :, (x + 1) % L, z, :] += fw; Xr[(x + 1) % L, z, :, x, z, :] += bw
                else: Xr[x, z, :, x, (z + 1) % L, :] += fw; Xr[x, (z + 1) % L, :, x, z, :] += bw
    for x in range(L):
        for z in range(L): Xr[x, z, :, x, z, :] += (4 - M0) * E4
    return X
_cache = {}
def qdens_axis(th2, th4, want_gw=False, chunk=8, T=None):
    L = len(th2)
    if (L, M0) not in _cache: _cache[(L, M0)] = block_static(L)
    T = T or L; X0 = _cache[(L, M0)]; n = 4 * L * L; ps = 2 * np.pi * np.arange(T) / T; q = np.zeros(n); gw = 0.0
    S2 = 1j * G4[1]; S4 = 1j * G4[3]; ii = np.arange(L); blocks = [(a, b) for a in ps for b in ps]
    for i0 in range(0, len(blocks), chunk):
        bl = blocks[i0:i0 + chunk]; Hs = np.empty((len(bl), n, n), complex)
        for j, (p2, p4) in enumerate(bl):
            f2 = th2 + p2; f4 = th4 + p4
            loc = (np.sin(f2)[:, None, None, None] * S2 - np.cos(f2)[:, None, None, None] * E4
                   + np.sin(f4)[None, :, None, None] * S4 - np.cos(f4)[None, :, None, None] * E4)
            X = X0.copy(); Xr = X.reshape(L, L, 4, L, L, 4)
            Xr[ii[:, None], ii[None, :], :, ii[:, None], ii[None, :], :] += loc
            Hs[j] = np.einsum('st,ktn->ksn', G5, X.reshape(L * L, 4, n)).reshape(n, n)
        w, v = np.linalg.eigh(Hs); sg = np.sign(w)
        q += np.einsum('bin,bn,bin->i', v, sg, v.conj()).real
        if want_gw:
            g5b = np.kron(np.eye(L * L), G5)
            for j in range(len(bl)):
                S = (v[j] * sg[j]) @ v[j].conj().T; D = np.eye(n) + g5b @ S
                gw = max(gw, np.abs(g5b @ D + D @ g5b - D @ g5b @ D).max(), np.abs(S @ S - np.eye(n)).max())
    q = q.reshape(L, L, 4).sum(-1) / (T * T)
    return (q, gw) if want_gw else q
def build_H_full(th):
    L = round(th.shape[1] ** 0.25); N = L ** 4; idx = np.arange(N).reshape((L,) * 4); xs = np.arange(N)
    H = np.zeros((4 * N, 4 * N), complex); H4 = H.reshape(N, 4, N, 4); H4[xs, :, xs, :] += (4 - M0) * G5
    for mu in range(4):
        sh = np.roll(idx, -1, axis=mu).reshape(-1); U = np.exp(1j * th[mu])
        H4[xs, :, sh, :] += U[:, None, None] * (G5 @ (G4[mu] - E4) / 2)
        H4[sh, :, xs, :] += U.conj()[:, None, None] * (-G5 @ (G4[mu] + E4) / 2)
    return H
def antideriv(Fx): return np.concatenate([[0.0], np.cumsum(Fx)[:-1]])
def rand_phase_field(L, rng):
    ph = rng.uniform(0, 2 * np.pi, L); f = np.exp(1j * ph)
    for k in range(L):
        mk = (-k) % L
        if mk < k: f[k] = np.conj(f[mk])
        if mk == k: f[k] = np.sign(np.cos(ph[k])) or 1.0
    return np.fft.ifft(f).real * np.sqrt(L)
def M1(L, T):      # order-2 kernel Pi (potentials), 4-sign combination + Richardson in eps
    rng = np.random.default_rng(1000 + L); r2 = rand_phase_field(L, rng); r4 = rand_phase_field(L, rng); out = {}
    for eps in (0.02, 0.04):
        qs = {(a, b): qdens_axis(a * eps * r2, b * eps * r4, T=T) for a in (1, -1) for b in (1, -1)}
        bil = (qs[(1, 1)] - qs[(1, -1)] - qs[(-1, 1)] + qs[(-1, -1)]) / 4 / eps ** 2
        out[eps] = np.fft.fft2(bil) / np.outer(np.fft.fft(r2), np.fft.fft(r4))
    return np.fft.ifft2((4 * out[0.02] - out[0.04]) / 3).real, float(np.abs(out[0.02] - out[0.04]).max())
def M2pair(L, n, m, T, eps=0.3, shift=0.0):   # single-mode F = eps cos(p x1), G = eps cos(k x3); returns R16, RL (complex, raw)
    x = np.arange(L); p = 2 * np.pi * n / L; k = 2 * np.pi * m / L
    th2 = antideriv(eps * np.cos(p * x)) + shift; th4 = antideriv(eps * np.cos(k * x)) + shift
    qY = np.array([qdens_axis(Y * th2, Y * th4, T=T) for Y in YS]); ph = np.exp(-1j * (p * x[:, None] + k * x[None, :]))
    c = [4 * (np.tensordot(w, qY, 1) * ph).sum() / L ** 2 / eps ** 2 for w in (W16, WL)]
    return c[0], c[1]
# ---------------- analysis helpers ----------------
def kernel_from_pi(L, pos):
    """F-kernel Q~ on the nonzero grid (half-site phase removed), partial-sum position kernel Q, gamma fit."""
    Pk = 2 * np.pi * np.fft.fftfreq(L); E = np.exp(1j * Pk) - 1; Pi = np.fft.fft2(pos)
    Qt = np.full((L, L), np.nan); ph = np.exp(1j * (Pk[:, None] + Pk[None, :]) / 2)
    z = Pi[1:, 1:] / np.outer(E[1:], E[1:]) * ph[1:, 1:]; Qt[1:, 1:] = z.real; im = np.abs(z.imag).max()
    h = L // 2; order = [(h + 1 + i) % L for i in range(L)]; Ps = pos[np.ix_(order, order)]
    Qs = np.zeros((L, L)); Qs[1:, 1:] = np.cumsum(np.cumsum(Ps, 0), 1)[:-1, :-1]
    Q = np.zeros((L, L)); Q[np.ix_(order, order)] = Qs
    return Qt, im, Q
def symfit(svals, tvals, y, deg):
    X = np.array([[a ** u * b ** v + a ** v * b ** u for u in range(deg + 1) for v in range(u, deg + 1 - u)]
                  for a, b in zip(svals, tvals)])
    c, *_ = np.linalg.lstsq(X, y, rcond=None); return 2 * c[0], np.abs(X @ c - y).max()
def gamma_fit(L, Qt, deg):
    s = np.sin(np.pi * np.fft.fftfreq(L)) ** 2; S, T, Y = [], [], []
    for i in range(1, L):
        for j in range(1, L):
            if i != L // 2 and j != L // 2: S.append(s[i]); T.append(s[j]); Y.append(Qt[i, j])
    return symfit(S, T, np.array(Y), deg)
def tdist(L): d = np.minimum(np.arange(L), L - np.arange(L)); return np.maximum(d[:, None], d[None, :])
def envelope(L, M):
    D = tdist(L); return np.array([np.abs(M[D == d]).max() for d in range(L // 2 + 1)])
def xi_fit(env, d0, d1):
    d = np.arange(d0, d1 + 1); sl = np.polyfit(d, np.log(env[d0:d1 + 1]), 1)[0]; return -1 / sl
def currents(L, Q, gam):
    """Luscher split of Q - gam delta: K1 (row partial sums), K3 (column of row sums); d*K = Q - gam delta."""
    R = Q.sum(0)      # sum over a (axis 0) for each b
    h = L // 2; order = [(h + 1 + i) % L for i in range(L)]
    K1 = np.zeros((L, L)); acc = np.zeros(L)
    for a in order:
        acc = acc + Q[a] - (R if a == 0 else 0); K1[a] = acc
    K3 = np.zeros((L, L)); acc = 0.0
    for b in order:
        acc += R[b] - (gam if b == 0 else 0); K3[0, b] = acc
    return K1, K3
def floor_of(L, pos):
    h = L // 2; return max(np.abs(pos[[0, h], :]).max(), np.abs(pos[:, [0, h]]).max())
def dmax_of(L, env, flo, cap=None):
    cap = cap or L // 2 - 1; ok = [d for d in range(2, cap + 1) if env[d] >= 30 * flo]; return max(ok) if ok else 2
def xi_rule(L, env, flo, cap=None):
    dm = dmax_of(L, env, flo, cap); return (xi_fit(env, 2, dm) if dm >= 3 else float('nan')), dm

