L8_M2_8_1_1_M0_1 = (-4.6361015764e-05, -0.0091864089512)    # luscher-L8 embedded value at m0 = 1.0, (8,1,1), T = 24

# ---------- P0 / K. exactness and live re-verification ----------
t = time.time(); rng = np.random.default_rng(20261025); L = 4
th2 = 0.3 * rng.normal(size=L); th4 = 0.3 * rng.normal(size=L)
qb, gw = qdens_axis(th2, th4, want_gw=True)
X4 = np.indices((L,) * 4); th = np.zeros((4,) + (L,) * 4); th[1] = th2[X4[0]]; th[3] = th4[X4[2]]
w, v = np.linalg.eigh(build_H_full(th.reshape(4, -1)))
qf = np.einsum('xn,n,xn->x', v, np.sign(w), v.conj()).real.reshape(L ** 4, 4).sum(1).reshape((L,) * 4); del v
dv = np.abs(qf - qb[:, None, :, None]).max()
check("P0 m0 = 1.0, 4^4: block (p2,p4) density = full dense 4D density (dim 1024); per block GW and sign(H)^2 = 1",
      dv < 1e-12 and gw < 1e-12, f"|q_block - q_full| {dv:.0e}, GW/proj {gw:.0e}, {time.time()-t:.1f}s")
t = time.time(); pos6, _ = M1(6, 24); d6 = np.abs(pos6 - np.array(DATA['M1']['1.0']['6'])).max()
a, b = M2pair(8, 1, 1, 24); a = (a * np.exp(1j * np.pi / 4)).real; b = (b * np.exp(1j * np.pi / 4)).real
e8 = m2("1.0", 8, 24, 1, 1); d8 = max(abs(a - e8[0]), abs(b - e8[1]))
dL8 = max(abs(a - L8_M2_8_1_1_M0_1[0]), abs(b - L8_M2_8_1_1_M0_1[1]))
M0 = 0.6; pos6b, _ = M1(6, 24); d6b = np.abs(pos6b - np.array(DATA['M1']['0.6']['6'])).max(); M0 = 1.0
check("K2 laptop re-run = embedded Mac-mini values: order-2 kernels on 6 x 24 x 6 x 24 (m0 = 1.0 and 0.6) and the "
      "single-mode 16 / doublet coefficients on 8 x 24 x 8 x 24 (m0 = 1.0), which also equal luscher-L8's m0 = 1.0 values",
      max(d6, d6b, d8) < 1e-10 and dL8 < 1e-10, f"kernels {d6:.0e}, {d6b:.0e}; single-mode {d8:.0e}; vs L8 {dL8:.0e}; {time.time()-t:.0f}s")

# ---------- P1-P4: per-charge order-2 kernel, m0 = 1.0, T = 24 ----------
def kernel_set(m0):
    D = DATA['M1'][m0]; LS = sorted(int(k) for k in D); POS = {L: np.array(D[str(L)]) for L in LS}
    KER = {L: kernel_from_pi(L, POS[L]) for L in LS}; ENV = {L: envelope(L, POS[L]) for L in LS}
    FLO = {L: floor_of(L, POS[L]) for L in LS}
    XI = {L: xi_rule(L, ENV[L], FLO[L]) for L in LS if L >= 10}
    dS = {L: KER[L][2].sum() / GAM - 1 for L in LS}
    return LS, POS, KER, ENV, FLO, XI, dS
LS, POS, KER, ENV, FLO, XI, dS = kernel_set("1.0")
print("m0 = 1.0 order-2 kernel (T = 24): envelope max|Pi| at d = 1..L/2-1; floor; xi (fit d = 2..d_max); dS = sum Q/gamma - 1")
for L in LS:
    print(f"  L={L:2d}: " + " ".join(f"{e:.1e}" for e in ENV[L][1:L // 2]) + f"  floor {FLO[L]:.0e}"
          + (f"  xi {XI[L][0]:.3f} (d<={XI[L][1]})" if L in XI else "") + f"  dS {dS[L]:+.3%}")
xv = np.array([XI[L][0] for L in (10, 12, 16)]); spread = (xv.max() - xv.min()) / xv.mean()
c12 = abs(KER[12][0][3, 3] - KER[16][0][4, 4]) / GAM
crit("P1 [L8] kernel decay lengths at L = 10, 12, 16 agree within 10%, and |Q~_12 - Q~_16| at (pi/2, pi/2) "
      "<= 1e-3 gamma", spread <= 0.10 and c12 <= 1e-3, f"xi spread {spread:.1%}; common momentum {c12:.1e} gamma")
CUR = {}
for L in (12, 16):
    Q = KER[L][2]; K1, K3 = currents(L, Q, Q.sum()); e1 = envelope(L, K1); e3 = envelope(L, K3)
    CUR[L] = (e1, e3, xi_rule(L, e1, FLO[L]), xi_rule(L, e3, FLO[L], cap=L // 2 - 2))
x1 = {L: CUR[L][2][0] for L in CUR}
crit("P1' [task] the Luscher-split current kernel K1 decays exponentially with decay lengths at L = 12 "
      "and 16 within 20%", abs(x1[12] / x1[16] - 1) <= 0.20 and all(np.isfinite(list(x1.values()))),
      f"xi(K1) L12 {x1[12]:.3f} (d<={CUR[12][2][1]}), L16 {x1[16]:.3f} (d<={CUR[16][2][1]})")
crit("P2 [L8] sum_ab Q within 1% of 2/(4 pi^2) for every L >= 10",
      all(abs(dS[L]) <= 0.01 for L in LS if L >= 10), ", ".join(f"L{L} {dS[L]:+.3%}" for L in LS))
e1, e3, (xk1, d1), (xk3, d3) = CUR[16]; tail = max(e1[7:].max(), e3[7:].max()) / GAM
crit("P3 [L8] on L = 16 the current tails at distance >= 7 are < 1e-3 gamma and xi(K1), xi(K3) are within 15% "
      "of xi(Pi)", tail < 1e-3 and abs(xk1 / XI[16][0] - 1) <= 0.15 and abs(xk3 / XI[16][0] - 1) <= 0.15,
      f"tail {tail:.0e} gamma; xi(K1) {xk1:.3f}, xi(K3) {xk3:.3f} (d<={d3}), xi(Pi) {XI[16][0]:.3f}")
plat = {}
for L in LS:
    _, K3d = currents(L, -0.25 * KER[L][2], 0.0); plat[L] = abs(K3d[0, L // 2]) / abs(GAML) - 1
crit("P4 [L8] the doublet's would-be gauge-invariant current has a NON-decaying tail |K3'(L/2)| = |gamma_L| "
      "within 2% on every L = 6..16", all(abs(plat[L]) <= 0.02 for L in LS), ", ".join(f"L{L} {plat[L]:+.2%}" for L in LS))
crit("P4' [task] the same tail within 10% on every L = 6..16", all(abs(plat[L]) <= 0.10 for L in LS),
      f"max |dev| {max(abs(x) for x in plat.values()):.2%}")

# ---------- P4b-P6, V: single-mode finite field (eps = 0.3), m0 = 1.0 ----------
def sv(L, n): return np.sin(np.pi * n / L) ** 2
M2v = {}
for k, v in DATA['M2'].items():
    m0, L, T, n, m, eps, sh = k.split(','); M2v[(m0, int(L), int(T), int(n), int(m), float(eps), sh)] = v
base = {(L, n, m): v for (m0, L, T, n, m, eps, sh), v in M2v.items() if m0 == "1.0" and eps == 0.3 and sh == "0"
        and T == (16 if L == 24 else 24)}
for (L, n, m) in list(base):
    base.setdefault((L, m, n), base[(L, n, m)])              # x1 <-> x3 mirror (R(n,m) = R(m,n) by symmetry)
pts = [(sv(L, n), sv(L, m), v) for (L, n, m), v in base.items() if L in (12, 16) and 2 * n != L and 2 * m != L]
cL, rL = symfit([p[0] for p in pts], [p[1] for p in pts], np.array([p[2][1] for p in pts]), 3)
diag = sorted((sv(L, n), L, n, v) for (L, n, m), v in base.items() if n == m and 2 * n != L)
print("m0 = 1.0 diagonal p = k: s = sin^2(p/2), L, R16, R_L/gamma_L:")
print("  " + "; ".join(f"{s:.3f} L{L} {v[0]:+.2e} {v[1]/GAML:.3f}" for s, L, n, v in diag if L >= 12))
crit("P4b [L8] pooled cubic fit of R_L (L = 12 grid + L = 16 points) has intercept within 3% of gamma_L",
      abs(cL / GAML - 1) <= 0.03, f"intercept/gamma_L {cL/GAML:.4f} (fit residual {rL:.0e}, {len(pts)} points)")
c16, r16 = symfit([p[0] for p in pts], [p[1] for p in pts], np.array([p[2][0] for p in pts]), 3)
mx16 = max(abs(v[0]) for v in base.values())
ex16 = np.log(base[(16, 2, 2)][0] / base[(16, 1, 1)][0]) / np.log(np.sqrt(sv(16, 2) / sv(16, 1)))
crit("P5 [L8] R16 fitted intercept <= 0.01 |gamma_L| and <= 0.05 max|R16|, and its |p|-exponent on the "
      "L = 16 diagonal (n = 1, 2) in [1.6, 2.4]",
      abs(c16) <= 0.01 * abs(GAML) and abs(c16) <= 0.05 * mx16 and 1.6 <= ex16 <= 2.4,
      f"intercept {c16:+.1e} (0.01|gamma_L| {0.01*abs(GAML):.1e}, 0.05 max|R16| {0.05*mx16:.1e}); exponent {ex16:.2f}")
r24 = np.array([base[(24, n, n)][0] for n in (1, 2, 3)]); ph24 = np.sqrt(np.array([sv(24, n) for n in (1, 2, 3)]))
ex24 = np.polyfit(np.log(ph24), np.log(np.abs(r24)), 1)[0]; one_sign = bool(np.all(r24 < 0) or np.all(r24 > 0))
crit("P5' [task] on L = 24 (T = 16) the 16's diagonal coefficient at n = 1, 2, 3 has one sign and vanishes "
      "like |p|^a with fitted a >= 1.8", one_sign and ex24 >= 1.8,
      "R16 " + ", ".join(f"{r:+.2e}" for r in r24) + f"; exponent {ex24:.2f}; R16/gamma_L at n=1 {abs(r24[0]/GAML):.0e}")
epsp = {(L, n, m): v for (m0, L, T, n, m, eps, sh), v in M2v.items() if m0 == "1.0" and eps == 0.15}
sc = {k: np.log2(base[k][0] / epsp[k][0]) + 2 for k in ((12, 1, 1), (16, 1, 1), (16, 2, 2))}
